      if (null != mp)
      {
        Plane meshPlane;
        if (MeshFacePlane(mp, out meshPlane))
        {
          meshPlane.Origin = pt;
          xform = Transform.PlaneToPlane(m_object_plane, meshPlane);
          rc = xform.IsValid;
        }
      }
      return rc;
    }

