private double Hypot(double x, double y)
    {
     double r;
     if (x == 0) return y;
     if (y == 0) return x;
     if (x < 0) x = -x;
     if (y < 0) y = -y;
     if (x < y) {r = x; x = y; y = r;}
     r = y / x;
     return x * Math.Sqrt(1 + r * r);    
    }
  }
}

