public override Transform CalculateTransform(RhinoViewport viewport, Point3d point)
    {
      Transform xform = new Transform(0);

      if (SetX)
        xform[0, 3] = point.X;
      else
        xform[0, 0] = 1.0;

      if (SetY)
        xform[1, 3] = point.Y;
      else
        xform[1, 1] = 1.0;

      if (SetZ)
        xform[2, 3] = point.Z;
      else
        xform[2, 2] = 1.0;

      xform[3, 3] = 1.0;

      return xform;
    }
  }
