      cameraDir.Unitize ();
      Camera.SetCameraDirection (cameraDir);

      var cameraUp = Camera.CameraUp;
      cameraUp.Unitize ();
      Camera.SetCameraUp (cameraUp);

      Renderer.Viewport = Camera;

      GL.Viewport (0, 0, BufferSize.Width, BufferSize.Height);
    }

    /// <summary>
