private int FindLayerFromId(File3dm file, Guid id)
    {
      if (null != file && id != Guid.Empty)
      {
        for (var i = 0; i < file.AllLayers.Count; i++)
        {
          if (file.AllLayers.FindIndex(i).Id == id)
            return i;
        }
      }
      return -1;
    }
  }
}

