protected override Result RunCommand(RhinoDoc doc, RunMode mode)
    {
      var go = new GetObject();
      go.SetCommandPrompt("Select curves");
      go.GeometryFilter = ObjectType.Curve;
      go.Get();
      if (go.CommandResult() != Result.Success)
        return go.CommandResult();

      var curve = go.Object(0).Curve();
      if (null == curve)
        return Result.Failure;

      var continuity = Continuity.G1_continuous;

      var gd = new GetOption();
      gd.SetCommandPrompt("Discontinuity to search");
      gd.AddOptionEnumList("Discontinuity", continuity);
      gd.AcceptNothing(true);
      var res = gd.Get();
      if (res == GetResult.Option)
      {
        var option = gd.Option();
        if (null == option)
          return Result.Failure;

        var list = Enum.GetValues(typeof (Continuity)).Cast<Continuity>().ToList();
        continuity = list[option.CurrentListOptionIndex];
      }
      else if (res != GetResult.Nothing)
        return Result.Cancel;

      var t0 = curve.Domain.Min;
      var t1 = curve.Domain.Max;

      var parameters = new List<double>();
      parameters.Add(t0);
      for (; ; )
      {
        double t;
        var rc = curve.GetNextDiscontinuity(continuity, t0, t1, out t);
        if (rc)
        {
          parameters.Add(t);
          t0 = t;
        }
        else
          break;
      }
      parameters.Add(t1);

      if (parameters.Count > 2)
      {
        for (var i = 0; i < parameters.Count - 1; i++)
        {
          t0 = parameters[i];
          t1 = parameters[i+1];
          var dom = new Interval(t0, t1);
          var new_curve = curve.Trim(dom);
          if (null != new_curve)
            doc.Objects.AddCurve(new_curve);
        }

        doc.Objects.Delete(go.Object(0), false);
      }

      return Result.Success;
    }
  }
}

using Rhino.Geometry;

var pt = new Point3d(-23.32, 44.53, 8.67);
var id = doc.Objects.AddPoint(pt);

protected override Result RunCommand(RhinoDoc doc, RunMode mode)
    {
      var filter = ObjectType.Surface | ObjectType.PolysrfFilter;
      ObjRef objref;
      var rc = RhinoGet.GetOneObject("Select surface or polysurface", false, filter, out objref);
      if (rc != Result.Success || objref == null)
        return rc;

      var rhobj = objref.Object();
      var brep = objref.Brep();
      if (rhobj == null || brep == null)
        return Result.Failure;

      rhobj.Select(false);

      var curves = new List<Curve>();
      foreach (var edge in brep.Edges)
      {
        // Find only the naked edges 
        if (edge.Valence == EdgeAdjacency.Naked)
        {
          var crv = edge.DuplicateCurve();
          if (crv.IsLinear())
            crv = new LineCurve(crv.PointAtStart, crv.PointAtEnd);
          curves.Add(crv);
        }
      }

      var tol = 2.1 * doc.ModelAbsoluteTolerance;
      var output = Curve.JoinCurves(curves, tol);
      for (var i = 0; i < output.Length; i++)
      {
        var id = doc.Objects.AddCurve(output[i]);
        doc.Objects.Select(id);
      }

      doc.Views.Redraw();
      return Result.Success;
    }
  }
}

