protected override void OnDynamicDraw(GetPointDrawEventArgs e)
    {
      if (Transform.IsValid && m_arc.IsValid)
      {
        var color = Rhino.ApplicationSettings.AppearanceSettings.DefaultObjectColor;
        e.Display.DrawArc(m_arc, color);

        var v0 = m_arc.StartPoint - m_arc.Center;
        v0 *= 1.5;
        e.Display.DrawLine(m_arc.Center, m_arc.Center + v0, color);

        v0 = m_arc.EndPoint - m_arc.Center;
        v0 *= 1.5;
        var v1 = (e.CurrentPoint - m_arc.Center);
        if (v1.SquareLength > v0.SquareLength)
          v0 = v1;
        e.Display.DrawLine(m_arc.Center, m_arc.Center + v0, color);

        if (m_angle < 0.0)
          e.Display.DrawPoint(m_arc.EndPoint, color);
        else
          e.Display.DrawPoint(m_arc.StartPoint, color);
        e.Display.DrawPoint(m_arc.Center, color);

        Rhino.UI.StatusBar.SetPointPane(e.CurrentPoint);
        Rhino.UI.StatusBar.SetDistancePane(m_angle * 180.0 / Math.PI);
      }

      base.OnDynamicDraw(e);
    }

protected override Result RunCommand(RhinoDoc doc, RunMode mode)
    {
      var view = doc.Views.ActiveView;
      if (null == view)
        return Result.Failure;

      var gz = new GetOption();
      gz.SetCommandPrompt("Zoom option");
      var b_opt = gz.AddOption("BoundingBox");
      var e_opt = gz.AddOption("Extents");
      var s_opt = gz.AddOption("Selected");
      gz.Get();
      if (gz.CommandResult() != Result.Success)
        return gz.CommandResult();

      var option = gz.Option();
      if (null == option)
        return Result.Failure;

      if (option.Index == b_opt)
      {
        var go = new GetObject();
        go.SetCommandPrompt("Select objects");
        go.SubObjectSelect = false;
        go.GetMultiple(1, 0);
        if (go.CommandResult() != Result.Success)
          return go.CommandResult();

        var bbox = new BoundingBox();
        for (var i = 0; i < go.ObjectCount; i++)
        {
          var geom = go.Object(i).Geometry();
          if (null != geom)
          {
            var b = geom.GetBoundingBox(true);
            if (b.IsValid)
            {
              if (0 == i)
                bbox = b;
              else
                bbox.Union(b);
            }
          }
        }

        if (bbox.IsValid)
        {
          view.ActiveViewport.ZoomBoundingBox(bbox);
          view.Redraw();
        }
      }
      else if (option.Index == e_opt)
      {
        view.ActiveViewport.ZoomExtents();
        view.Redraw();
      }
      else if (option.Index == s_opt)
      {
        view.ActiveViewport.ZoomExtentsSelected();
        view.Redraw();
      }

      return Result.Success;
    }
  }
}

