protected override Result RunCommand(RhinoDoc doc, RunMode mode)
    {
      ObjRef objref;
      var rc = RhinoGet.GetOneObject("Select object to move", false, ObjectType.AnyObject, out objref);
      if (rc != Result.Success)
        return rc;
      if (null == objref)
        return Result.Failure;

      Point3d first_point;
      rc = RhinoGet.GetPoint("Point to move from", false, out first_point);
      if (rc != Result.Success)
        return rc;

      var gp = new GetPoint();
      gp.SetCommandPrompt("Point to move to");
      gp.SetBasePoint(first_point, true);
      gp.DrawLineFromPoint(first_point, true);
      gp.Get();
      rc = gp.CommandResult();
      if (rc != Result.Success)
        return rc;

      var second_point = gp.Point();

      var dir = second_point - first_point;
      if (dir.Length > RhinoMath.ZeroTolerance)
      {
        var xform = Transform.Translation(dir);
        doc.Objects.Transform(objref, xform, true);
        doc.Views.Redraw();
      }

      return rc;
    }
  }
}

public Point3d CalculateClosestPoint(Point3d point)
    {
      var closest_point = Point3d.Unset;
      var minimum_distance = Double.MaxValue;
      foreach (var brep in Breps)
      {
        foreach (var face in brep.Faces)
        {
          double u, v;
          if (face.ClosestPoint(point, out u, out v))
          {
            var face_point = face.PointAt(u, v);
            double distance = face_point.DistanceTo(point);
            if (distance < minimum_distance)
            {
              minimum_distance = distance;
              closest_point = face_point;
            }
          }
        }
      }
      return closest_point;
    }

