public static bool IsHoleLoop(Brep brep, int loopIndex, bool bPlanarCheck, bool bBoundaryCheck, double tolerance)
    {
      var loop = (null != brep) ? brep.Loops[loopIndex] : null;
      if (null == loop )
        return false;

      if (BrepLoopType.Inner != loop.LoopType)
        return false;

      var face = brep.Faces[loop.Face.FaceIndex];
      if (null == face)
        return false;

      var srf = face.UnderlyingSurface();
      if (null == srf)
        return false;

      if (bPlanarCheck)
      {
        if ((1 != srf.Degree(0) && 1 != srf.Degree(1)) || 
            (1 != srf.SpanCount(0) && 1 != srf.SpanCount(1)) || 
            !srf.IsPlanar(tolerance))
        return false;
      }

      for (var lti = 0; lti < loop.Trims.Count; lti++)
      {
        var ti = loop.Trims[lti].TrimIndex;
        var trim = brep.Trims[ti];
        if (null == trim )
          return false;

        var edge = brep.Edges[trim.Edge.EdgeIndex];
        if (null == edge)
          return false;

        var edge_ti = edge.TrimIndices();
        if (0 == edge_ti.Length)
          return false;

        switch (edge.TrimCount)
        {
        case 1:
          {
            if (ti != edge_ti[0])
              return false;
          }
          break;
        case 2:
          {
            if (bBoundaryCheck )
              return false;

            int other_ti;
            if (ti == edge_ti[0])
              other_ti = edge_ti[1];
            else if (ti == edge_ti[1])
              other_ti = edge_ti[0];
            else
              return false;

            var other_trim = brep.Trims[other_ti];
            if (null == other_trim)
              return false;

            var other_loop = brep.Loops[other_trim.Loop.LoopIndex];
            if (null == other_loop)
              return false;

            if (BrepLoopType.Outer != other_loop.LoopType)
              return false;

            if (other_loop.Face.FaceIndex == loop.Face.FaceIndex)
              return false;
          }
          break;

        default:
          return false;
        }
      }

      return true;
    }
  }

}

public void SetupCamera ()
		{
			if (Camera == null)
				LoadCamera ();

			// Fix up viewport values
			var cameraDir = Camera.CameraDirection;
			cameraDir.Unitize ();
			Camera.SetCameraDirection (cameraDir);

			var cameraUp = Camera.CameraUp;
			cameraUp.Unitize ();
			Camera.SetCameraUp (cameraUp);

			Renderer.Viewport = Camera;

			// save initial viewport settings for restoreView
			InitialPosition = new ViewportInfo (Camera);
			LastPosition = new ViewportInfo (Camera);
			CameraIsAtInitialPosition = true;

			GL.Viewport (0, 0, (int)View.Bounds.Size.Width, (int)View.Bounds.Size.Height);
		}

		/// <summary>
		/// Find the Perspective viewport in the 3dm file and sets up the default view.
		/// </summary>

private Guid[] ScriptedSweep2(RhinoDoc doc, Guid rail1, Guid rail2, IEnumerable<Guid> shapes)
    {
      doc.Objects.UnselectAll(true);

      var sb = new StringBuilder("_-Sweep2 ");
      sb.Append(string.Format("_SelID {0} ", rail1));
      sb.Append(string.Format("_SelID {0} ", rail2));
      foreach (var shape in shapes)
        sb.Append(string.Format("_SelID {0} ", shape));
      sb.Append(string.Format("_Enter "));
      sb.Append(string.Format("_Simplify=_None _Closed=_Yes _MaintainHeight=_Yes _Enter"));

      var start_sn = Rhino.DocObjects.RhinoObject.NextRuntimeSerialNumber;
      RhinoApp.RunScript(sb.ToString(), false);
      var end_sn = Rhino.DocObjects.RhinoObject.NextRuntimeSerialNumber;
      if (start_sn == end_sn)
        return new Guid[0];

      var object_ids = new List<Guid>();
      for (var sn = start_sn; sn < end_sn; sn++)
      {
        var obj = doc.Objects.Find(sn);
        if (null != obj)
          object_ids.Add(obj.Id);
      }

      return object_ids.ToArray();
    }
  }
}

