        rLight = light_geometry;
        return true;
      }
      else
      {
        // If not in doc, check if light matches custom light and return it
        foreach (Rhino.Geometry.Light custom_light in m_light_array)
        {
          if (custom_light.Id == uuid)
          {
            rLight = custom_light;
            return true;
          }
        }
      }
      return false;
    }

