      if (!userdata.TryGetString("ObjName", out name))
        return false;

      for (int i = 0; i < archive_array.Count; i++)
      {
        var ba = archive_array.Get(i);
        var ud = ba.ReadDictionary();

        string s = "";

        if (ud.TryGetString("ObjName", out s))
        {
          if (0 == s.CompareTo(name))
            return true;
        }
      }

      return false;
    }
  }
