void
AddSphere(Point3d center) {
_doc.Objects.AddSphere(
new
Sphere(center, 3));
}
private
void
RhinoObjectAdded(Object sender, RhinoObjectEventArgs e)
{
var
message = String.Format(
"thread id = {0}, obj id = {1}"
,
Thread.CurrentThread.ManagedThreadId,
e.ObjectId.ToString());
RhinoApp.WriteLine(message);
try
{
// when a sphere is added from a secondary thread this line will
// throw an exception because UI controls can only be accessed from
// the main UI thread
_label.Content = message;
}
catch
(InvalidOperationException ioe) {RhinoApp.WriteLine(ioe.Message);}
}
private
void
RhinoObjectAddedSafe(Object sender, RhinoObjectEventArgs e)
{
var
message = String.Format(
"thread id = {0}, obj id = {1}"
,
Thread.CurrentThread.ManagedThreadId,
e.ObjectId.ToString());
RhinoApp.WriteLine(message);
// checks if the calling thread is the thread the dispatcher is associated with.
// In other words, checks if the calling thread is the UI thread
if
(_label.Dispatcher.CheckAccess())
// if we're on the UI thread then just update the component
_label.Content = message;
else
{
// invoke the setLabelTextDelegate on the thread the dispatcher is associated with, i.e., the UI thread
var
setLabelTextDelegate =
new
Action<
string
>(txt => _label.Content = txt);
_label.Dispatcher.BeginInvoke(setLabelTextDelegate,
new
String[] { message });
}
}
}
