{
  public static Rhino.Commands.Result AddCylinder(Rhino.RhinoDoc doc)
  {
    Rhino.Geometry.Point3d center_point = new Rhino.Geometry.Point3d(0, 0, 0);
    Rhino.Geometry.Point3d height_point = new Rhino.Geometry.Point3d(0, 0, 10);
    Rhino.Geometry.Vector3d zaxis = height_point - center_point;
    Rhino.Geometry.Plane plane = new Rhino.Geometry.Plane(center_point, zaxis);
    const double radius = 5;
    Rhino.Geometry.Circle circle = new Rhino.Geometry.Circle(plane, radius);
    Rhino.Geometry.Cylinder cylinder = new Rhino.Geometry.Cylinder(circle, zaxis.Length);
    Rhino.Geometry.Brep brep = cylinder.ToBrep(true, true);
    if (brep != null)
    {
      doc.Objects.AddBrep(brep);
      doc.Views.Redraw();
    }
    return Rhino.Commands.Result.Success;
  }
}

protected override Result RunCommand(RhinoDoc doc, RunMode mode)
    {
      var gp = new GetPoint();
      gp.SetCommandPrompt("Pick a point");
      gp.Get();
      if (gp.CommandResult() != Result.Success)
        return gp.CommandResult();

      var point = gp.Point();

      var format = string.Format("F{0}", doc.DistanceDisplayPrecision);
      var provider = CultureInfo.InvariantCulture;

      var x = point.X.ToString(format, provider);
      var y = point.Y.ToString(format, provider);
      var z = point.Z.ToString(format, provider);
      RhinoApp.WriteLine("World coordinates: {0},{1},{2}", x, y, z);

      var view = gp.View();
      if (null != view)
      {
        var plane = view.ActiveViewport.ConstructionPlane();
        var xform = Transform.ChangeBasis(Plane.WorldXY, plane);

        point.Transform(xform);

        x = point.X.ToString(format, provider);
        y = point.Y.ToString(format, provider);
        z = point.Z.ToString(format, provider);
        RhinoApp.WriteLine("CPlane coordinates: {0},{1},{2}", x, y, z);
      }

      return Result.Success;
    }
  }
}

