      go.SubObjectSelect = false;
      go.GetMultiple(1, 0);
      if (go.CommandResult() != Result.Success)
        return go.CommandResult();

      for (int i = 0; i < go.ObjectCount; i++)
      {
        var obj = go.Object(i).Object();
        if (null != obj)
          obj.Select(true);
