      if (go.ObjectsWerePreselected)
      {
        for (int i = 0; i < go.ObjectCount; i++)
        {
          var obj = go.Object(i).Object();
          if (null != obj)
            obj.Select(true);
        }
      }

      doc.Views.RedrawEnabled = true;

      return Result.Success; 
    }
  }
